lib = '''def line_coords(grid, orient):
    """Sorted distinct perpendicular offsets of colored lines: rows if orient=='h', else j-i diagonals."""
    h, w = len(grid), len(grid[0])
    cells = [(i, j) for i in range(h) for j in range(w) if grid[i][j]]
    if orient == 'h':
        return sorted({i for i, j in cells}), (lambda i, j: i)
    return sorted({j - i for i, j in cells}), (lambda i, j: j - i)

def tile_lines(grid, orient='d'):
    """Tile every colored line along its perpendicular with period = number of lines; each period slot takes that line's color."""
    coords, key = line_coords(grid, orient)
    p = len(coords)
    h, w = len(grid), len(grid[0])
    cmap = {}
    for i in range(h):
        for j in range(w):
            if grid[i][j]:
                cmap[key(i, j) % p] = grid[i][j]
    return [[cmap[key(i, j) % p] for j in range(w)] for i in range(h)]
'''
